template<bool Silu>
static inline activation piecewise(activation value) {
#pragma HLS INLINE
    const unsigned raw=c209mp::bits(value).to_uint();
    const bool negative=bool(raw&0x8000u);
    const unsigned magnitude_bits=raw&0x7fffu;
    // No nonfinite input can become a ROM address.
    if((magnitude_bits&0x7c00u)==0x7c00u) {
        if(magnitude_bits&0x03ffu)return value;
        return negative?activation(0):value;
    }
    activation magnitude=c209mp::from_bits(c209mp::word(magnitude_bits));
    if(magnitude>=activation(Silu?12:8))
        return negative?activation(0):value;
    activation scaled=magnitude*activation(32);
#pragma HLS BIND_OP variable=scaled op=hmul impl=fulldsp
    // Address conversion only: ordinary payload/arithmetic remains binary16.
    unsigned address=unsigned(c209mp::widen(scaled));
    activation fraction=scaled-activation(address);
#pragma HLS BIND_OP variable=fraction op=hsub impl=fulldsp
    uint32_t coefficient=Silu?silu_coefficient(address):gelu_coefficient(address);
    activation base=c209mp::from_bits(c209mp::word(coefficient&0xffffu));
    activation change=c209mp::from_bits(c209mp::word(coefficient>>16));
    activation interpolation=change*fraction;
#pragma HLS BIND_OP variable=interpolation op=hmul impl=fulldsp
    activation correction=base+interpolation;
#pragma HLS BIND_OP variable=correction op=hadd impl=fulldsp
    activation positive=value-correction;
#pragma HLS BIND_OP variable=positive op=hsub impl=fulldsp
    // Vendor half unary '-' promotes in native C++; sign inversion is a wire.
    if(negative)return c209mp::from_bits(c209mp::word(c209mp::bits(correction).to_uint()^0x8000u));
    return positive;
}
static inline activation gelu(activation value) {return piecewise<false>(value);}
static inline activation silu(activation value) {return piecewise<true>(value);}
#else
static inline activation gelu(activation value) {
    // The legacy numerical regression association is intentionally unchanged.
    return .5f*value*(1.f+hls::tanhf(.7978845608f*(value+.044715f*value*value*value)));
}
static inline activation silu(activation value) {return value/(1.f+hls::expf(-value));}
#endif
